import { prisma } from '../db/prisma.js';
import { economicSourceDelta } from '../lib/economic-debt.js';

/** Read-only, owner-scoped financial context for the shared Planner assistant.
 * Amounts are decimal strings of kopecks and IDs are database IDs, never
 * generated by the language model. Restrict array sizes and exposed fields. */
export async function readPlannerEconomicOverview(owner: string) {
  if (!await prisma.economicAccount.findFirst({where:{userId:owner},select:{id:true}})) {
    await prisma.economicAccount.upsert({
      where:{userId_name:{userId:owner,name:'Основной счёт'}},
      create:{userId:owner,name:'Основной счёт',isPrimary:true},update:{}
    });
  }
  const [accounts, sources, incoming, categories, recentOperations, debts, loans] = await Promise.all([
    prisma.economicAccount.findMany({
      where:{userId:owner},orderBy:[{isPrimary:'desc'},{createdAt:'asc'}],take:100,
      select:{id:true,name:true,openingBalanceMinor:true,isPrimary:true,updatedAt:true}
    }),
    prisma.economicOperation.groupBy({
      by:['sourceAccountId','kind'],where:{userId:owner},_sum:{amountMinor:true}
    }),
    prisma.economicOperation.groupBy({
      by:['targetAccountId'],where:{userId:owner,kind:'TRANSFER',targetAccountId:{not:null}},_sum:{amountMinor:true}
    }),
    prisma.economicCategory.findMany({
      where:{userId:owner},orderBy:{createdAt:'desc'},take:80,
      select:{id:true,name:true,kind:true,createdAt:true}
    }),
    prisma.economicOperation.findMany({
      where:{userId:owner},orderBy:[{occurredAt:'desc'},{id:'desc'}],take:15,
      select:{id:true,kind:true,title:true,category:true,amountMinor:true,
        sourceAccountId:true,targetAccountId:true,occurredAt:true,updatedAt:true,debtId:true}
    }),
    prisma.economicDebt.findMany({
      where:{userId:owner,isClosed:false},orderBy:{updatedAt:'desc'},take:20,
      select:{id:true,counterparty:true,direction:true,amountMinor:true,paidMinor:true,
        accountId:true,dueAt:true,updatedAt:true}
    }),
    prisma.economicLoan.findMany({
      where:{userId:owner,isClosed:false},orderBy:{updatedAt:'desc'},take:20,
      select:{id:true,name:true,lender:true,principalMinor:true,paidMinor:true,
        annualRateBps:true,termMonths:true,updatedAt:true}
    })
  ]);
  const balance=new Map(accounts.map(a=>[a.id,a.openingBalanceMinor]));
  for(const row of sources) if(balance.has(row.sourceAccountId))
    balance.set(row.sourceAccountId,(balance.get(row.sourceAccountId)??0n)+
      economicSourceDelta(row.kind,row._sum.amountMinor??0n));
  for(const row of incoming) if(row.targetAccountId&&balance.has(row.targetAccountId))
    balance.set(row.targetAccountId,(balance.get(row.targetAccountId)??0n)+(row._sum.amountMinor??0n));
  return {
    currency:'RUB',minorUnit:'kopecks',rublesPer100Minor:1,
    accounts:accounts.map(a=>({
      id:a.id,name:a.name,isPrimary:a.isPrimary,
      balanceMinor:(balance.get(a.id)??0n).toString(),updatedAt:a.updatedAt.toISOString()
    })),
    categories:categories.map(c=>({...c,createdAt:c.createdAt.toISOString()})),
    recentOperations:recentOperations.map(o=>({...o,amountMinor:o.amountMinor.toString(),
      occurredAt:o.occurredAt.toISOString(),updatedAt:o.updatedAt.toISOString()})),
    debts:debts.map(d=>({...d,amountMinor:d.amountMinor.toString(),paidMinor:d.paidMinor.toString(),
      dueAt:d.dueAt?.toISOString()??null,updatedAt:d.updatedAt.toISOString()})),
    loans:loans.map(l=>({...l,principalMinor:l.principalMinor.toString(),paidMinor:l.paidMinor.toString(),
      updatedAt:l.updatedAt.toISOString()}))
  };
}

/** No permissive model-side IDs: actions must refer to a record returned by a
 * successful scoped lookup or by readPlannerEconomicOverview in this request. */
export type EconomicObservedRecord = {
  entity:'account'|'operation'|'debt'|'loan'|'category';
  id:string;version:string;
};
